import sys
from collections import defaultdict
import heapq

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    H = int(data[0])
    W = int(data[1])
    M = int(data[2])

    targets = []
    for i in range(M):
        h = int(data[3 + 2 * i])
        w = int(data[4 + 2 * i])
        targets.append((h, w))

    row_count = defaultdict(int)
    col_count = defaultdict(int)

    for h, w in targets:
        row_count[h] += 1
        col_count[w] += 1

    max_heap = []
    for h, count in row_count.items():
        heapq.heappush(max_heap, (-count, 'row', h))
    for w, count in col_count.items():
        heapq.heappush(max_heap, (-count, 'col', w))

    destroyed = set()
    result = 0

    while max_heap:
        count, kind, index = heapq.heappop(max_heap)
        count = -count

        if kind == 'row':
            if index in destroyed:
                continue
            destroyed.add(index)
            result += count
            for h, w in targets:
                if h == index:
                    col_count[w] -= 1
                    if col_count[w] > 0:
                        heapq.heappush(max_heap, (-col_count[w], 'col', w))
        else:
            if index in destroyed:
                continue
            destroyed.add(index)
            result += count
            for h, w in targets:
                if w == index:
                    row_count[h] -= 1
                    if row_count[h] > 0:
                        heapq.heappush(max_heap, (-row_count[h], 'row', h))

    print(result)

if __name__ == "__main__":
    main()
